import React, { createContext, useState, useContext } from 'react';

// Create the context
const PortfolioContext = createContext();

// Create a provider component
export const PortfolioProvider = ({ children }) => {
  const [portfolio, setPortfolio] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showSummaryPrompt, setShowSummaryPrompt] = useState(false);
  const [portfolioHistory, setPortfolioHistory] = useState([]);

  // Function to process transactions file
  const processTransactionsFile = async (file, headers, mappedFields, portfolioName = 'My Portfolio') => {
    setLoading(true);
    setError(null);

    try {
      // Read the file
      const text = await readFileAsText(file);
      const lines = text.split('\n');

      if (lines.length <= 1) {
        throw new Error('File is empty or contains only headers');
      }

      // Parse headers
      const headerLine = lines[0];
      const headerFields = headerLine.split(',').map(h => h.trim());

      // Parse transactions
      const transactions = [];
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue; // Skip empty lines

        const values = line.split(',').map(v => v.trim());
        const transaction = {};

        // Map fields based on the provided mappings
        Object.keys(mappedFields).forEach(field => {
          const headerIndex = headerFields.indexOf(mappedFields[field]);
          if (headerIndex !== -1) {
            transaction[field] = values[headerIndex];
          }
        });

        // Add only if we have the minimum required fields
        if (transaction.symbol && transaction.date && transaction.action && transaction.quantity && transaction.price) {
          // Convert quantity and price to numbers
          transaction.quantity = parseFloat(transaction.quantity);
          transaction.price = parseFloat(transaction.price);
          transaction.brokerage = transaction.brokerage ? parseFloat(transaction.brokerage) : 0;

          transactions.push(transaction);
        }
      }

      // Calculate portfolio summary from transactions
      const holdings = calculateHoldings(transactions);

      // Simulate getting current prices (in a real app, this would call Yahoo Finance API)
      const holdingsWithCurrentPrices = simulateCurrentPrices(holdings);

      // Create portfolio object
      const newPortfolio = {
        name: portfolioName,
        type: 'Transactions-based',
        lastUpdated: new Date().toISOString(),
        transactions: transactions,
        holdings: holdingsWithCurrentPrices,
        totalValue: holdingsWithCurrentPrices.reduce((sum, h) => sum + h.currentValue, 0),
        investedValue: holdingsWithCurrentPrices.reduce((sum, h) => sum + h.valueAtCost, 0),
        performanceMetrics: calculatePerformanceMetrics(holdingsWithCurrentPrices, transactions),
        history: [{
          date: new Date().toISOString(),
          action: 'Created',
          totalValue: holdingsWithCurrentPrices.reduce((sum, h) => sum + h.currentValue, 0),
          investedValue: holdingsWithCurrentPrices.reduce((sum, h) => sum + h.valueAtCost, 0)
        }]
      };

      // Calculate sector allocation
      newPortfolio.sectorAllocation = calculateSectorAllocation(holdingsWithCurrentPrices);

      // Calculate unrealized return
      if (newPortfolio.investedValue > 0) {
        newPortfolio.unrealizedReturn = ((newPortfolio.totalValue - newPortfolio.investedValue) / newPortfolio.investedValue) * 100;
      } else {
        newPortfolio.unrealizedReturn = 0;
      }

      setPortfolio(newPortfolio);
      setLoading(false);
      setShowSummaryPrompt(true); // Show prompt to add summary file

      // Add to portfolio history
      setPortfolioHistory(prev => [...prev, {
        date: new Date().toISOString(),
        action: 'Created portfolio from transactions',
        portfolioName: portfolioName
      }]);

      return newPortfolio;

    } catch (error) {
      console.error('Error processing transactions file:', error);
      setError('Failed to process transactions file: ' + error.message);
      setLoading(false);
      return null;
    }
  };

  // Function to update transactions file
  const updateTransactionsFile = async (file, headers, mappedFields) => {
    if (!portfolio) {
      return processTransactionsFile(file, headers, mappedFields);
    }

    setLoading(true);
    setError(null);

    try {
      // Read the file
      const text = await readFileAsText(file);
      const lines = text.split('\n');

      if (lines.length <= 1) {
        throw new Error('File is empty or contains only headers');
      }

      // Parse headers
      const headerLine = lines[0];
      const headerFields = headerLine.split(',').map(h => h.trim());

      // Parse transactions
      const transactions = [];
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue; // Skip empty lines

        const values = line.split(',').map(v => v.trim());
        const transaction = {};

        // Map fields based on the provided mappings
        Object.keys(mappedFields).forEach(field => {
          const headerIndex = headerFields.indexOf(mappedFields[field]);
          if (headerIndex !== -1) {
            transaction[field] = values[headerIndex];
          }
        });

        // Add only if we have the minimum required fields
        if (transaction.symbol && transaction.date && transaction.action && transaction.quantity && transaction.price) {
          // Convert quantity and price to numbers
          transaction.quantity = parseFloat(transaction.quantity);
          transaction.price = parseFloat(transaction.price);
          transaction.brokerage = transaction.brokerage ? parseFloat(transaction.brokerage) : 0;

          transactions.push(transaction);
        }
      }

      // Calculate portfolio summary from transactions
      const holdings = calculateHoldings(transactions);

      // Simulate getting current prices (in a real app, this would call Yahoo Finance API)
      const holdingsWithCurrentPrices = simulateCurrentPrices(holdings);

      // Create updated portfolio object
      const updatedPortfolio = {
        ...portfolio,
        type: 'Transactions-based',
        lastUpdated: new Date().toISOString(),
        transactions: transactions,
        holdings: holdingsWithCurrentPrices,
        totalValue: holdingsWithCurrentPrices.reduce((sum, h) => sum + h.currentValue, 0),
        investedValue: holdingsWithCurrentPrices.reduce((sum, h) => sum + h.valueAtCost, 0),
        performanceMetrics: calculatePerformanceMetrics(holdingsWithCurrentPrices, transactions)
      };

      // Calculate sector allocation
      updatedPortfolio.sectorAllocation = calculateSectorAllocation(holdingsWithCurrentPrices);

      // Calculate unrealized return
      if (updatedPortfolio.investedValue > 0) {
        updatedPortfolio.unrealizedReturn = ((updatedPortfolio.totalValue - updatedPortfolio.investedValue) / updatedPortfolio.investedValue) * 100;
      } else {
        updatedPortfolio.unrealizedReturn = 0;
      }

      // Add history entry
      if (!updatedPortfolio.history) {
        updatedPortfolio.history = [];
      }

      updatedPortfolio.history.push({
        date: new Date().toISOString(),
        action: 'Updated transactions',
        totalValue: updatedPortfolio.totalValue,
        investedValue: updatedPortfolio.investedValue
      });

      setPortfolio(updatedPortfolio);
      setLoading(false);
      setShowSummaryPrompt(true); // Show prompt to add summary file

      // Add to portfolio history
      setPortfolioHistory(prev => [...prev, {
        date: new Date().toISOString(),
        action: 'Updated portfolio transactions',
        portfolioName: updatedPortfolio.name
      }]);

      return updatedPortfolio;

    } catch (error) {
      console.error('Error updating transactions file:', error);
      setError('Failed to update transactions file: ' + error.message);
      setLoading(false);
      return null;
    }
  };

  // Function to process summary file
  const processSummaryFile = async (file, headers, mappedFields, portfolioName = 'My Portfolio') => {
    setLoading(true);
    setError(null);

    try {
      // Read the file
      const text = await readFileAsText(file);
      const lines = text.split('\n');

      if (lines.length <= 1) {
        throw new Error('File is empty or contains only headers');
      }

      // Parse headers
      const headerLine = lines[0];
      const headerFields = headerLine.split(',').map(h => h.trim());

      // Parse holdings
      const holdings = [];
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue; // Skip empty lines

        const values = line.split(',').map(v => v.trim());
        const holding = {};

        // Map fields based on the provided mappings
        Object.keys(mappedFields).forEach(field => {
          const headerIndex = headerFields.indexOf(mappedFields[field]);
          if (headerIndex !== -1) {
            holding[field] = values[headerIndex];
          }
        });

        // Add only if we have the minimum required fields and quantity > 0
        if (holding.symbol && holding.quantity && parseFloat(holding.quantity) > 0) {
          // Convert numeric fields
          holding.quantity = parseFloat(holding.quantity);
          holding.avgCostPrice = parseFloat(holding.avgCostPrice) || 0;
          holding.currentPrice = parseFloat(holding.currentPrice) || 0;

          // Calculate values if not provided
          holding.valueAtCost = parseFloat(holding.valueAtCost) || (holding.quantity * holding.avgCostPrice);
          holding.currentValue = parseFloat(holding.valueAtMarket) || (holding.quantity * holding.currentPrice);
          holding.unrealizedPL = parseFloat(holding.unrealizedPL) || (holding.currentValue - holding.valueAtCost);

          // Calculate unrealized P/L percent if not provided
          if (!holding.unrealizedPLPercent && holding.valueAtCost > 0) {
            holding.unrealizedPLPercent = (holding.unrealizedPL / holding.valueAtCost) * 100;
          } else {
            holding.unrealizedPLPercent = parseFloat(holding.unrealizedPLPercent) || 0;
          }

          // Assign a sector (in a real app, this would come from an API or database)
          holding.sector = assignSector(holding.symbol, holding.companyName);

          holdings.push(holding);
        }
      }

      // If we already have a portfolio with transactions, update it with the summary data
      if (portfolio && portfolio.type === 'Transactions-based') {
        // Create a map of existing holdings by symbol
        const existingHoldingsMap = {};
        portfolio.holdings.forEach(h => {
          existingHoldingsMap[h.symbol] = h;
        });

        // Update existing holdings with summary data or add new ones
        holdings.forEach(holding => {
          if (existingHoldingsMap[holding.symbol]) {
            // Update current price and market value from summary
            existingHoldingsMap[holding.symbol].currentPrice = holding.currentPrice;
            existingHoldingsMap[holding.symbol].currentValue = holding.currentValue;
            existingHoldingsMap[holding.symbol].unrealizedPL = holding.unrealizedPL;
            existingHoldingsMap[holding.symbol].unrealizedPLPercent = holding.unrealizedPLPercent;
          } else {
            // Add new holding that wasn't in transactions
            portfolio.holdings.push(holding);
          }
        });

        // Recalculate portfolio totals
        const updatedPortfolio = {
          ...portfolio,
          totalValue: portfolio.holdings.reduce((sum, h) => sum + h.currentValue, 0),
          lastUpdated: new Date().toISOString()
        };

        // Recalculate unrealized return
        if (updatedPortfolio.investedValue > 0) {
          updatedPortfolio.unrealizedReturn = ((updatedPortfolio.totalValue - updatedPortfolio.investedValue) / updatedPortfolio.investedValue) * 100;
        }

        // Recalculate sector allocation
        updatedPortfolio.sectorAllocation = calculateSectorAllocation(updatedPortfolio.holdings);

        // Add history entry
        if (!updatedPortfolio.history) {
          updatedPortfolio.history = [];
        }

        updatedPortfolio.history.push({
          date: new Date().toISOString(),
          action: 'Updated with summary data',
          totalValue: updatedPortfolio.totalValue,
          investedValue: updatedPortfolio.investedValue
        });

        setPortfolio(updatedPortfolio);
        setLoading(false);
        setShowSummaryPrompt(false);

        // Add to portfolio history
        setPortfolioHistory(prev => [...prev, {
          date: new Date().toISOString(),
          action: 'Updated portfolio with summary data',
          portfolioName: updatedPortfolio.name
        }]);

        return updatedPortfolio;
      } else {
        // Calculate total values
        const totalValue = holdings.reduce((sum, h) => sum + h.currentValue, 0);
        const investedValue = holdings.reduce((sum, h) => sum + h.valueAtCost, 0);

        // Calculate allocation percentages
        holdings.forEach(holding => {
          holding.allocation = (holding.currentValue / totalValue) * 100;
        });

        // Create portfolio object
        const newPortfolio = {
          name: portfolioName,
          type: 'Summary-based',
          lastUpdated: new Date().toISOString(),
          holdings: holdings,
          totalValue: totalValue,
          investedValue: investedValue,
          performanceMetrics: {
            xirr: 12.5, // Placeholder value
            sharpeRatio: 1.2,
            volatility: 14.5,
            drawdown: 8.2,
            alpha: 2.1,
            beta: 0.95
          },
          history: [{
            date: new Date().toISOString(),
            action: 'Created',
            totalValue: totalValue,
            investedValue: investedValue
          }]
        };

        // Calculate sector allocation
        newPortfolio.sectorAllocation = calculateSectorAllocation(holdings);

        // Calculate unrealized return
        if (investedValue > 0) {
          newPortfolio.unrealizedReturn = ((totalValue - investedValue) / investedValue) * 100;
        } else {
          newPortfolio.unrealizedReturn = 0;
        }

        setPortfolio(newPortfolio);
        setLoading(false);
        setShowSummaryPrompt(false);

        // Add to portfolio history
        setPortfolioHistory(prev => [...prev, {
          date: new Date().toISOString(),
          action: 'Created portfolio from summary',
          portfolioName: portfolioName
        }]);

        return newPortfolio;
      }

    } catch (error) {
      console.error('Error processing summary file:', error);
      setError('Failed to process summary file: ' + error.message);
      setLoading(false);
      return null;
    }
  };

  // Function to update portfolio name
  const updatePortfolioName = (newName) => {
    if (!portfolio) return;

    const updatedPortfolio = {
      ...portfolio,
      name: newName
    };

    setPortfolio(updatedPortfolio);

    // Add to portfolio history
    setPortfolioHistory(prev => [...prev, {
      date: new Date().toISOString(),
      action: 'Updated portfolio name',
      portfolioName: newName
    }]);

    return updatedPortfolio;
  };

  // Helper function to read file as text
  const readFileAsText = (file) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => resolve(event.target.result);
      reader.onerror = (error) => reject(error);
      reader.readAsText(file);
    });
  };

  // Helper function to calculate holdings from transactions
  const calculateHoldings = (transactions) => {
    const holdingsMap = {};

    transactions.forEach(transaction => {
      const symbol = transaction.symbol;
      const quantity = transaction.quantity;
      const price = transaction.price;
      const action = transaction.action.toLowerCase();
      const value = quantity * price;

      if (!holdingsMap[symbol]) {
        holdingsMap[symbol] = {
          symbol: symbol,
          name: transaction.companyName || symbol,
          quantity: 0,
          totalCost: 0,
          totalSold: 0,
          totalSoldValue: 0,
          realizedPL: 0
        };
      }

      const holding = holdingsMap[symbol];

      if (action === 'buy') {
        const newQuantity = holding.quantity + quantity;
        const newTotalCost = holding.totalCost + value;
        holding.avgCostPrice = newTotalCost / newQuantity;
        holding.quantity = newQuantity;
        holding.totalCost = newTotalCost;
      } else if (action === 'sell') {
        holding.quantity -= quantity;
        holding.totalSold += quantity;
        holding.totalSoldValue += value;

        // Calculate realized P/L for this sale
        const costBasis = quantity * holding.avgCostPrice;
        const saleValue = value;
        const realizedPL = saleValue - costBasis;
        holding.realizedPL += realizedPL;

        // Adjust total cost for remaining shares
        if (holding.quantity > 0) {
          holding.totalCost = holding.avgCostPrice * holding.quantity;
        } else {
          holding.totalCost = 0;
          holding.avgCostPrice = 0;
        }
      }
    });

    // Convert map to array and filter out positions with zero quantity
    return Object.values(holdingsMap)
      .filter(holding => holding.quantity > 0)
      .map(holding => ({
        symbol: holding.symbol,
        name: holding.name,
        quantity: holding.quantity,
        avgCostPrice: holding.avgCostPrice,
        valueAtCost: holding.quantity * holding.avgCostPrice,
        realizedPL: holding.realizedPL,
        sector: assignSector(holding.symbol, holding.name)
      }));
  };

  // Helper function to simulate current prices
  const simulateCurrentPrices = (holdings) => {
    return holdings.map(holding => {
      // Simulate a current price that's +/- 20% from the average cost
      const randomFactor = 0.8 + (Math.random() * 0.4); // Between 0.8 and 1.2
      const currentPrice = holding.avgCostPrice * randomFactor;
      const currentValue = holding.quantity * currentPrice;
      const unrealizedPL = currentValue - holding.valueAtCost;
      const unrealizedPLPercent = (unrealizedPL / holding.valueAtCost) * 100;

      return {
        ...holding,
        currentPrice,
        currentValue,
        unrealizedPL,
        unrealizedPLPercent
      };
    });
  };

  // Helper function to calculate performance metrics
  const calculatePerformanceMetrics = (holdings, transactions) => {
    // In a real app, these would be calculated based on actual data
    // For now, we'll use placeholder values
    return {
      xirr: 14.5,
      sharpeRatio: 1.8,
      volatility: 15.2,
      drawdown: 8.5,
      alpha: 2.3,
      beta: 0.92
    };
  };

  // Helper function to calculate sector allocation
  const calculateSectorAllocation = (holdings) => {
    const sectorMap = {};
    const totalValue = holdings.reduce((sum, h) => sum + (h.currentValue || 0), 0);

    if (totalValue === 0) return [];

    holdings.forEach(holding => {
      const sector = holding.sector || 'Other';
      if (!sectorMap[sector]) {
        sectorMap[sector] = 0;
      }
      sectorMap[sector] += (holding.currentValue || 0);
    });

    return Object.entries(sectorMap).map(([sector, value]) => ({
      sector,
      percentage: (value / totalValue) * 100
    }));
  };

  // Helper function to assign a sector based on symbol or company name
  const assignSector = (symbol, companyName) => {
    // In a real app, this would use an API or database
    // For now, we'll use a simple mapping based on keywords
    const sectorKeywords = {
      'Technology': ['tech', 'software', 'hardware', 'semiconductor', 'apple', 'microsoft', 'google', 'amazon', 'meta', 'nvidia'],
      'Financial Services': ['bank', 'insurance', 'finance', 'financial', 'capital', 'jpmorgan', 'visa', 'mastercard'],
      'Healthcare': ['health', 'pharma', 'medical', 'biotech', 'pfizer', 'johnson', 'unitedhealth'],
      'Consumer Discretionary': ['retail', 'consumer', 'luxury', 'restaurant', 'travel', 'amazon', 'tesla', 'mcdonald'],
      'Consumer Staples': ['food', 'beverage', 'household', 'personal', 'walmart', 'coca-cola', 'pepsi'],
      'Industrials': ['industrial', 'manufacturing', 'aerospace', 'defense', 'transportation', 'boeing', 'caterpillar'],
      'Energy': ['oil', 'gas', 'energy', 'renewable', 'exxon', 'chevron', 'shell'],
      'Materials': ['material', 'chemical', 'mining', 'metal', 'steel', 'gold', 'silver'],
      'Utilities': ['utility', 'electric', 'water', 'gas', 'power', 'nextera', 'duke'],
      'Real Estate': ['real estate', 'property', 'reit', 'american tower', 'prologis'],
      'Communication Services': ['telecom', 'media', 'entertainment', 'verizon', 'at&t', 'comcast', 'netflix']
    };

    const name = (companyName || symbol || '').toLowerCase();

    for (const [sector, keywords] of Object.entries(sectorKeywords)) {
      if (keywords.some(keyword => name.includes(keyword.toLowerCase()))) {
        return sector;
      }
    }

    return 'Other';
  };

  // Clear portfolio data
  const clearPortfolio = () => {
    setPortfolio(null);
    setError(null);
    setShowSummaryPrompt(false);
  };

  // Dismiss summary prompt
  const dismissSummaryPrompt = () => {
    setShowSummaryPrompt(false);
  };

  return (
    <PortfolioContext.Provider
      value={{
        portfolio,
        loading,
        error,
        showSummaryPrompt,
        portfolioHistory,
        processTransactionsFile,
        processSummaryFile,
        updateTransactionsFile,
        updatePortfolioName,
        clearPortfolio,
        dismissSummaryPrompt
      }}
    >
      {children}
    </PortfolioContext.Provider>
  );
};

// Custom hook to use the portfolio context
export const usePortfolio = () => {
  const context = useContext(PortfolioContext);
  if (!context) {
    throw new Error('usePortfolio must be used within a PortfolioProvider');
  }
  return context;
};

export default PortfolioContext;
